 action="{{ route('tasks.status',$t) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Selesai"><button class="btn">Tandai selesai</button></form></div></article>@empty<div class="card empty">Belum ada tugas aktif. <a href="{{ route('tasks.create') }}">Tambah tugas pertama</a>.</div>@endforelse</div></main></div><nav class="mobile-nav"><a href="{{ route('dashboard') }}">◈ Dashboard</a><a href="{{ route('tasks.index') }}">▤ Tugas</a><a href="{{ route('tasks.create') }}">＋ Tambah</a></nav>@endsection